def blocks(path,magic,stride=None):
 result=[]
 with path.open('rb') as f:
  assert f.read(8)==magic;f.read(24 if magic==b'RORDTAIL' else 8)
  while f.read(4)==b'DATA':
   n,size,crc=struct.unpack('<III',f.read(12));data=f.read(size);assert zlib.crc32(data)==crc and f.read(4)==b'DONE'
   result.extend([data[i*stride:(i+1)*stride] for i in range(n)] if stride else [data])
 return result
plt.rcParams.update({'font.family':'DejaVu Sans','font.size':10,'figure.facecolor':'#101e2b','axes.facecolor':'#101e2b','text.color':'#e2eef6','axes.labelcolor':'#bfcedb','axes.edgecolor':'#60788b','xtick.color':'#bfcedb','ytick.color':'#bfcedb','grid.color':'#354958','savefig.facecolor':'#101e2b'})
selected=[];series={}
for scenario in ['impact-yield-v1','impact-fracture-v1']:
 v=next(x for x in verification['runs'] if x['definition']['scenario']==scenario and x['definition']['detailFault']=='none');archive=Path(v['archivePath']);rs=blocks(archive/'steps.rort',b'RORTRIAL',2080);ds=blocks(archive/'detail.rort',b'RORDTAIL');trigger=v['metrics']['impactDetail']['triggerTick']
 def d(r,at):return struct.unpack_from('<d',r,at)[0]
 def f(r,at):return struct.unpack_from('<f',r,at)[0]
 events=[]
 for r in rs:
  tick=struct.unpack_from('<Q',r)[0]
  for i in range(struct.unpack_from('<I',r,1368)[0]):
   at=1376+i*88;events.append(dict(tick=tick,kind=struct.unpack_from('<I',r,at+4)[0],oldRestM=d(r,at+16),newRestM=d(r,at+24),oldStrengthN=d(r,at+48),newStrengthN=d(r,at+56),restPortJ=d(r,1232),removalPortJ=d(r,1240)))
 force=[];impulse=0;peak=0;contacts=0
 for frame in ds:
  count=struct.unpack_from('<I',frame,28)[0];net=0
  for i in range(count):
   at=128+4*256+3*112+i*104
   if struct.unpack_from('<I',frame,at+12)[0]:net+=f(frame,at+64);contacts+=1
  force.append(net);impulse+=net*d(frame,8);peak=max(peak,abs(net))
 check=v['metrics']['impactDetail'];assert abs(impulse-check['barrierImpulseNs'][0])<1e-8 and peak==check['peakNetBarrierForceN'] and contacts==check['barrierApplications']
 series[scenario]=dict(time=[(struct.unpack_from('<Q',r)[0]-trigger)*d(r,24) for r in rs],kinetic=[d(r,144) for r in rs],elastic=[d(r,1160) for r in rs],denseTime=[(struct.unpack_from('<Q',r)[0]-trigger)*d(r,8) for r in ds],rest=[f(r,1152+20) for r in ds],strength=[f(r,1152+36) for r in ds],force=force)
 selected.append(dict(id=v['id'],scenario=scenario,timeline=v['metrics']['impactTimeline'],detail=check,events=events,restPortJ=sum(d(r,1232) for r in rs),removalPortJ=sum(d(r,1240) for r in rs),finalStrengthN=f(ds[-1],1152+36),finalRestM=f(ds[-1],1152+20),rawWindowBytes=(archive/'detail.rort').stat().st_size,profile=read(archive/'detail-profile.json'),qualification=v['metrics']['qualification']))
fig,axes=plt.subplots(3,1,figsize=(10,7),sharex=True)
for key,color in [('impact-yield-v1','#52c9b9'),('impact-fracture-v1','#f7bc6a')]:
 s=series[key];label='Yield / weakening' if 'yield' in key else 'Removal';axes[0].plot(s['denseTime'],s['force'],color=color,label=label,lw=.9);axes[1].plot(s['denseTime'],s['rest'],color=color,lw=1);axes[2].plot(s['denseTime'],s['strength'],color=color,lw=1)
axes[0].set_ylabel('Barrier force X / N');axes[1].set_ylabel('Rest length / m');axes[2].set_ylabel('Strength / N');axes[2].set_xlabel('Physics seconds relative to first consumed contact');axes[0].legend(loc='lower right');axes[0].set_title('Actual 2 kHz native detail: collision first, material-state changes later')
for ax in axes:ax.set_xlim(-.1,.8);ax.axvline(0,color='#a9c0d0',ls='--',lw=.8);ax.grid(alpha=.3)
