axes[-1].set_xlabel('Physics seconds relative to first consumed contact');fig.tight_layout(pad=1.6);fig.savefig(media/'energy-state.png',dpi=160);plt.close(fig)
summary=dict(session=str(root),sourceHead=source['head'],sourceWasDirty=bool(source['dirty']),nativeSha256=build['sha256'],nativeInputs=len(source['nativeSourceHashes']),nativeProcesses=len(allruns),outcomes={'CompletePassed':sum(v['capture']=='Complete' and v['validation']=='Passed' for v in allruns),'IncompleteNotReady':sum(v['capture']=='Incomplete' and v['validation']=='NotReady' for v in allruns)},repeats=verification['checks'],selected=selected,uiChecks=ui['checks'],media=read(media/'playback/playback-check.json'),retention='All native originals, failed harness logs and adversarial copies retained; no automatic cleanup',scope='Per-step native-law conformance, not independent full-trajectory prediction or physical material calibration')
